import fs from 'node:fs';
import { assetPath } from '../reports/pdf/assets.js';

/**
 * Steward's own map styles (#234, ADR 0015): light and dark, for vector tiles in the OpenMapTiles schema (OpenFreeMap,
 * many own tile servers, PMTiles files built with that schema) and in the Protomaps schema (PMTiles files from a
 * Protomaps build; generated by scripts/map-styles.mjs into server/assets/map/), and the raster layer for
 * OpenStreetMap and own raster sources – dimmed in the dark theme, never inverted (inverted maps mislead).
 *
 * The styles name no glyphs URL and no sprite: MapLibre draws the labels with the browser's own fonts, so nothing
 * besides the tiles is fetched and a self-hosted file works with nothing else. Every layer reads the source "base".
 */

export type MapTheme = 'light' | 'dark';
export type Layer = Record<string, unknown>;

interface Palette {
  background: string;
  land: string;
  farmland: string;
  wood: string;
  park: string;
  residential: string;
  water: string;
  building: string;
  minor: string;
  major: string;
  motorway: string;
  casing: string;
  boundary: string;
  text: string;
  halo: string;
}

const PALETTES: Record<MapTheme, Palette> = {
  light: {
    background: '#f2efe9',
    land: '#e6eedb',
    farmland: '#eef0e0',
    wood: '#d4e3c4',
    park: '#d3e6c4',
    residential: '#ebe7e1',
    water: '#a9cfe0',
    building: '#ddd8cf',
    minor: '#ffffff',
    major: '#fbd9a6',
    motorway: '#f3b49c',
    casing: '#cbc4b9',
    boundary: '#8f8ca0',
    text: '#2f3337',
    halo: '#ffffff',
  },
  dark: {
    background: '#1d2125',
    land: '#22282c',
    farmland: '#24292d',
    wood: '#223029',
    park: '#22302a',
    residential: '#262a2f',
    water: '#18303f',
    building: '#30353c',
    minor: '#3b4249',
    major: '#5b5141',
    motorway: '#684a3f',
    casing: '#15181b',
    boundary: '#6f7480',
    text: '#d3d6d9',
    halo: '#1d2125',
  },
};

const name = (lang: string) => ['coalesce', ['get', `name:${lang}`], ['get', 'name_int'], ['get', 'name']];
const FONT = ['Noto Sans Regular'];
const FONT_BOLD = ['Noto Sans Bold'];
const width = (base: number) => ['interpolate', ['exponential', 1.4], ['zoom'], 5, base * 0.4, 12, base * 1.6, 18, base * 8];

/** A style for the OpenMapTiles schema (layer and class names as published by openmaptiles.org). */
export function openMapTilesLayers(theme: MapTheme, lang: string): Layer[] {
  const p = PALETTES[theme];
  const roads = (id: string, classes: string[], color: string, w: number, minzoom = 0): Layer[] => [
    {
      id: `${id}-casing`,
      type: 'line',
      source: 'base',
      'source-layer': 'transportation',
      minzoom: Math.max(minzoom, 8),
      filter: ['match', ['get', 'class'], classes, true, false],
      layout: { 'line-cap': 'round', 'line-join': 'round' },
      paint: { 'line-color': p.casing, 'line-width': width(w + 0.8) },
    },
    {
      id,
      type: 'line',
      source: 'base',
      'source-layer': 'transportation',
      minzoom,
      filter: ['match', ['get', 'class'], classes, true, false],
      layout: { 'line-cap': 'round', 'line-join': 'round' },
      paint: { 'line-color': color, 'line-width': width(w) },
    },
  ];
  return [
    { id: 'background', type: 'background', paint: { 'background-color': p.background } },
    {
      id: 'landcover',
      type: 'fill',
      source: 'base',
      'source-layer': 'landcover',
      paint: {
        'fill-color': ['match', ['get', 'class'], 'wood', p.wood, 'forest', p.wood, 'farmland', p.farmland, p.land],
        'fill-opacity': 0.8,
      },
    },
    {
      id: 'landuse-residential',
      type: 'fill',
      source: 'base',
      'source-layer': 'landuse',
      filter: ['match', ['get', 'class'], ['residential', 'suburb', 'neighbourhood', 'industrial', 'commercial'], true, false],
      paint: { 'fill-color': p.residential, 'fill-opacity': 0.7 },
    },
    { id: 'park', type: 'fill', source: 'base', 'source-layer': 'park', paint: { 'fill-color': p.park, 'fill-opacity': 0.8 } },
    { id: 'water', type: 'fill', source: 'base', 'source-layer': 'water', paint: { 'fill-color': p.water } },
    {
      id: 'waterway',
      type: 'line',
      source: 'base',
      'source-layer': 'waterway',
      minzoom: 8,
      paint: { 'line-color': p.water, 'line-width': ['interpolate', ['linear'], ['zoom'], 8, 0.5, 16, 3] },
    },
    { id: 'building', type: 'fill', source: 'base', 'source-layer': 'building', minzoom: 13, paint: { 'fill-color': p.building } },
    ...roads('road-minor', ['minor', 'service', 'track', 'path'], p.minor, 0.8, 11),
    ...roads('road-major', ['primary', 'secondary', 'tertiary', 'trunk'], p.major, 1.2, 6),
    ...roads('road-motorway', ['motorway'], p.motorway, 1.5, 4),
    {
      id: 'boundary',
      type: 'line',
      source: 'base',
      'source-layer': 'boundary',
      filter: ['<=', ['to-number', ['get', 'admin_level'], 10], 4],
      paint: { 'line-color': p.boundary, 'line-width': 1, 'line-dasharray': [3, 2] },
    },
    {
      id: 'road-label',
      type: 'symbol',
      source: 'base',
      'source-layer': 'transportation_name',
      minzoom: 14,
      layout: { 'symbol-placement': 'line', 'text-field': name(lang), 'text-font': FONT, 'text-size': 11 },
      paint: { 'text-color': p.text, 'text-halo-color': p.halo, 'text-halo-width': 1.5 },
    },
    {
      id: 'place-label',
      type: 'symbol',
      source: 'base',
      'source-layer': 'place',
      layout: {
        'text-field': name(lang),
        'text-font': ['match', ['get', 'class'], ['city', 'country', 'state'], ['literal', FONT_BOLD], ['literal', FONT]],
        'text-size': ['match', ['get', 'class'], 'country', 14, 'state', 13, 'city', 15, 'town', 13, 12],
        'text-max-width': 8,
      },
      paint: { 'text-color': p.text, 'text-halo-color': p.halo, 'text-halo-width': 1.5 },
    },
  ];
}

const protomaps = new Map<MapTheme, Layer[]>();
/** The generated Protomaps-schema style, with the labels in `lang` (the file is generated for English). */
export function protomapsLayers(theme: MapTheme, lang: string): Layer[] {
  let layers = protomaps.get(theme);
  if (!layers) {
    layers = (JSON.parse(fs.readFileSync(assetPath(`map/protomaps-${theme}.json`), 'utf8')) as { layers: Layer[] }).layers;
    protomaps.set(theme, layers);
  }
  if (lang === 'en') return layers;
  // the labels ask for name:en first; another language asks for its own name first (the rest stays as generated)
  return JSON.parse(JSON.stringify(layers).replaceAll('"name:en"', JSON.stringify(`name:${lang}`))) as Layer[];
}

/** A raster source as one layer over the background; dimmed in the dark theme. */
export function rasterLayers(theme: MapTheme): Layer[] {
  return [
    { id: 'background', type: 'background', paint: { 'background-color': PALETTES[theme].background } },
    {
      id: 'tiles',
      type: 'raster',
      source: 'base',
      paint:
        theme === 'dark'
          ? { 'raster-brightness-max': 0.62, 'raster-brightness-min': 0.04, 'raster-saturation': -0.45, 'raster-contrast': 0.08 }
          : { 'raster-fade-duration': 150 },
    },
  ];
}
